const byCity = new Map(Object.entries(data).map(([city, districts]) => [city, new Map(Object.entries(districts))]));

/** The streets to offer: all of a city's when it has no districts of streets, otherwise those of the chosen districts. */
export function streetsIn(city: string, districts: string[]): string[] {
  const inCity = byCity.get(city);
  if (!inCity) return [];
  const chosen = inCity.get("") ?? districts.flatMap((district) => inCity.get(district) ?? []);
  return [...new Set(chosen)].sort((a, b) => a.localeCompare(b, "ka"));
}
